const { url, enabledEvents, description, connect, metadata } = $.input;

if (!url) throw new Error('url is required');
if (!enabledEvents || !enabledEvents.length) throw new Error('enabledEvents is required');

const formData = { url };

enabledEvents.forEach((event, i) => {
  formData[`enabled_events[${i}]`] = event;
});

if (description) formData.description = description;
if (connect !== undefined) formData.connect = String(connect);

if (metadata && typeof metadata === 'object') {
  Object.entries(metadata).forEach(([key, value]) => {
    formData[`metadata[${key}]`] = String(value);
  });
}

return { formData };

const resp = $.steps.createWebhook.response || {};

if (resp.error) {
  return {
    success: false,
    error: resp.error.message || 'Failed to create webhook endpoint',
    details: resp.error
  };
}

return {
  success: true,
  webhookId: resp.id || '',
  secret: resp.secret || '',
  url: resp.url || '',
  status: resp.status || '',
  enabledEvents: resp.enabled_events || [],
  livemode: resp.livemode || false,
  summary: resp.id
    ? `Created webhook ${resp.id} for ${(resp.enabled_events || []).length} event type(s). SAVE THE SECRET -- it won't be shown again.`
    : 'Failed to create webhook endpoint'
};
